+        statusMessage.textContent = 'Please select a notification preference before submitting.';
+        statusMessage.dataset.state = 'error';
+        form.querySelector('input[name="notificationPreference"]').focus();
+        return;
+      }
+
+      statusMessage.textContent = 'Preference saved: ' + selectedOption.value + '.';
+      statusMessage.dataset.state = 'success';
+    });
+  </script>
+</body>
+</html>
