      margin: 0;
      min-height: 100vh;
      font-family: Arial, Helvetica, sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 30%),
        linear-gradient(180deg, #0a0f1d 0%, #111a2e 100%);
      color: var(--text);
    }

