      margin: 0 0 0.75rem;
      font-size: clamp(1.75rem, 4vw, 2.3rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 1.5rem;
      color: var(--muted);
      line-height: 1.5;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      margin: 0;
    }

    fieldset {
      margin: 0;
      padding: 1.25rem;
      border: 1px solid var(--panel-border);
      border-radius: 1rem;
      background: rgba(8, 14, 30, 0.62);
    }

    legend {
      padding: 0 0.5rem;
      font-size: 1.05rem;
      font-weight: 700;
    }

    .radio-group {
      display: grid;
      gap: 0.75rem;
      margin-top: 0.5rem;
    }

    .radio-option {
      display: flex;
      align-items: center;
      gap: 0.85rem;
      padding: 0.95rem 1rem;
      border: 1px solid transparent;
      border-radius: 0.9rem;
      background: rgba(255, 255, 255, 0.03);
      transition: border-color 0.2s ease, background-color 0.2s ease, transform 0.2s ease;
    }

    .radio-option:hover {
      border-color: #47568f;
      background: rgba(124, 156, 255, 0.08);
    }

    .radio-option:focus-within {
      border-color: var(--accent-strong);
      background: rgba(124, 156, 255, 0.12);
      outline: 2px solid transparent;
      box-shadow: 0 0 0 3px rgba(157, 178, 255, 0.3);
    }

    input[type="radio"] {
      margin: 0;
      inline-size: 1.15rem;
      block-size: 1.15rem;
      accent-color: var(--accent-strong);
    }

    label {
      font-size: 1rem;
      font-weight: 600;
      cursor: pointer;
