      font-size: 1rem;
      font-weight: 800;
      cursor: pointer;
    }

    button:hover {
      filter: brightness(1.05);
    }

    button:focus-visible,
    input[type="radio"]:focus-visible {
      outline: 3px solid var(--text);
      outline-offset: 3px;
    }

    .status-message {
      min-height: 1.5rem;
      margin: 0;
      font-weight: 700;
      color: var(--success);
    }

    .status-message[data-state="error"] {
      color: var(--error);
    }

    @media (max-width: 480px) {
      .card {
        padding: 1.25rem;
      }

      fieldset {
        padding: 1rem;
      }

      .radio-option {
        align-items: flex-start;
      }

      button {
        width: 100%;
        justify-self: stretch;
      }
    }

    @media (forced-colors: active) {
      .skip-link,
