      .radio-option,
      button {
        border: 1px solid ButtonText;
        background: Canvas;
        color: CanvasText;
        box-shadow: none;
      }

      button:focus-visible,
      input[type="radio"]:focus-visible,
      .skip-link:focus,
      .radio-option:focus-within {
        outline-color: Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <section class="card" aria-labelledby="page-title">
      <h1 id="page-title">Notification Preferences</h1>
      <p class="intro">Choose the one way you would like to receive updates from us.</p>

      <form id="notification-form">
        <div class="form-field">
          <fieldset>
            <legend>How do you prefer to receive notifications?</legend>
            <div class="radio-group">
              <label class="radio-option" for="notify-email">
                <input id="notify-email" type="radio" name="notificationPreference" value="Email" required>
                <span>Email</span>
              </label>
              <label class="radio-option" for="notify-sms">
                <input id="notify-sms" type="radio" name="notificationPreference" value="SMS">
                <span>SMS</span>
              </label>
              <label class="radio-option" for="notify-push">
                <input id="notify-push" type="radio" name="notificationPreference" value="Push Notifications">
                <span>Push Notifications</span>
              </label>
            </div>
          </fieldset>
        </div>

        <button type="submit">Submit</button>
        <p id="form-status" class="status-message" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('notification-form');
    const statusMessage = document.getElementById('form-status');

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const selectedOption = form.querySelector('input[name="notificationPreference"]:checked');

      if (!selectedOption) {
        statusMessage.textContent = 'Please select a notification preference before submitting.';
        statusMessage.dataset.state = 'error';
        form.querySelector('input[name="notificationPreference"]').focus();
        return;
      }

      statusMessage.textContent = 'Preference saved: ' + selectedOption.value + '.';
      statusMessage.dataset.state = 'success';
    });
  </script>
</body>
</html>
